{
    "name": "Black Martini",
	"description": "Black Martini is a famous cocktail beverage served at parties and special occasions, with plenty of variations.",
    "github": "Donearm",

    "ingredients": [
        {
            "quantity": "30",
            "measure": "ml",
            "ingredient": "gin"
        },
        {
            "quantity": "15",
            "measure": "ml",
            "ingredient": "black sambuca"
        },
        {
            "quantity": "1",
            "measure": "",
            "ingredient": "lemon twist"
        }
    ],
    "directions": [
		"Combine ingredients in a shaker and shake with ice until chilled.",
		"Strain into a cocktail glass.",
		"Garnish with a lemon twist."
    ],
    "image": "black-martini.jpg",
        "keywords": [
		"alcoholic",
		"gin",
		"lemon",
		"sambuca"
        ]

}

{
    "name": "Embuscade",
    "description": "A French beer-based cocktail from Normandy. Refreshing and slightly sweet.",
    "github": "WilliamAboucaya",
    "ingredients": [
        {
            "quantity": "10",
            "measure": "cl",
            "ingredient": "cold lager"
        },
        {
            "quantity": "6",
            "measure": "cl",
            "ingredient": "white wine, preferably dry"
        },
        {
            "quantity": "4",
            "measure": "cl",
            "ingredient": "Calvados apple brandy"
        },
        {
            "quantity": "2",
            "measure": "cl",
            "ingredient": "blackcurrant syrup"
        },
        {
            "quantity": "2",
            "measure": "cl",
            "ingredient": "lemon juice"
        }
    ],
    "directions": [
        "Pour the blackcurrant syrup and the lemon juice in a glass",
        "Stir well with a spoon",
        "Add the white wine and the Calvados brandy",
        "Stir again",
        "Add the cold beer slowly"
    ],
    "image": "embuscade.jpg",
    "keywords": [
        "beer",
        "blackcurrant",
        "calvados",
        "french"
    ]
}

{
    "name": "Mind Eraser",
    "description": "The drink that will literally erase your mind after drinking it! Prepare to forget!",
    "github": "jhkim8268",
    "ingredients": [
        {
            "quantity": "1",
            "measure": "oz",
            "ingredient": "Kahlúa"
        },
        {
            "quantity": "2",
            "measure": "oz",
            "ingredient": "Vodka"
        },
        {
            "quantity": "2",
            "measure": "oz",
            "ingredient": "Club soda"
        }
    ],
    "directions": [
        "Pour 1 ounce of Kahlúa in a rocks glass with ice.",
        "Float 2 ounces of vodka on top, pouring down the side of the glass so that it separates.",
        "Top with 2 ounces of club soda, poured down the side of the glass in the same way."
    ],
    "image": "mind-eraser.jpg",
    "keywords": [
        "kahlúa",
        "vodka",
        "club soda"
    ]
}

{
    "name": "Monaco",
    "description": "A monaco is an alcoholic beverage made up of beer mixed with lemonade and grenadine syrup.",
    "github": "siffreinsg",
    "ingredients": [
        {
            "quantity": "5",
            "measure": "oz",
            "ingredient": "Beer"
        },
        {
            "quantity": "0.3",
            "measure": "oz",
            "ingredient": "Grenadine syrup"
        },
        {
            "quantity": "2",
            "measure": "oz",
            "ingredient": "Lemonade"
        }
    ],
    "directions": [
        "Mix everything together starting with the syrup.",
        "And drink!"
    ],
    "image": "monaco.jpg",
    "keywords": ["beer", "lemonade"]
}

{
    "name": "Venus Flytrap",
    "description": "The Venus Flytrip is a delicious sweet but not too sweet gin drink. It's very summer, but also somehow very holiday.",
    "github": "kristina-hager",
    "ingredients": [
        {
            "quantity": "1",
            "measure": "cup",
            "ingredient": "crushed ice"
        },
        {
            "quantity": "2",
            "measure": "oz",
            "ingredient": "gin infused with kefir lime"
        },
        {
            "quantity": "1",
            "measure": "oz",
            "ingredient": "Falernum (West Indies lime based sweetener)"
        },
        {
            "quantity": ".5",
            "measure": "oz",
            "ingredient": "lime juice"
        },
        {
            "quantity": ".5",
            "measure": "oz",
            "ingredient": "soda"
        },
        {
            "quantity": "1",
            "measure": "dash",
            "ingredient": "angostura bitters"
        },
        {
            "quantity": "3",
            "measure": "dash",
            "ingredient": "absinthe"
        },
        {
            "quantity": "1",
            "measure": "dash",
            "ingredient": "nutmeg"
        },
        {
            "quantity": "1",
            "measure": "",
            "ingredient": "kefir lime leaf"
        },
        {
            "quantity": "1",
            "measure": "",
            "ingredient": "wedge of lime"
        }
    ],
    "directions": [
        "To make the gin infusion: blend the gin with keffir lime leaves. Combine 1 double kefir lime leaf per 2oz gin.",
        "Strain the result through a cheesecloth and retain infused gin.",
        "Combine infused gin, other liquid ingredients, and crushed ice with a blender.",
        "Serve in a fancy glass with lime slice, keffir leaf and dash of nutmeg as garnish."
    ],
    "image": "venus-flytrap.jpg",
    "keywords": [
        "alcoholic",
        "gin",
        "bitters"
    ]
}

{
    "name": "White Bear",
    "description": "The White Bear is a simple but powerful starter cocktail based on Champagne and Vodka.",
    "github": "4ndrej",
    "ingredients": [
        {
            "quantity": "100",
            "measure": "ml",
            "ingredient": "Champagne"
        },
        {
            "quantity": "50",
            "measure": "ml",
            "ingredient": "Vodka"
        },
        {
            "quantity": "",
            "measure": "",
            "ingredient": "Ice"
        },
        {
            "quantity": "1",
            "measure": "wedge",
            "ingredient": "Lemon"
        }
    ],
    "directions": [
        "Optional: Put some ice into champagne glass.",
        "Add Champagne and Vodka.",
        "Stir gently to release some bubbles.",
        "Garnish with a lemon wedge."
    ],
    "image": "white-bear.jpg",
    "keywords": [
        "champagne",
        "vodka",
        "lemon",
        "hard",
        "alcoholic",
        "vegan"
    ]
}

